.ac-main{max-width:1200px;margin:0 auto;padding:24px 16px 64px}
.ac-overline{margin:0 0 6px;color:var(--ac-gold);font-size:11px;font-weight:600;letter-spacing:.14em;text-transform:uppercase}
.ac-hero{border:1px solid var(--ac-line);border-radius:14px;padding:24px;background:radial-gradient(120% 140% at 100% 0%,rgba(209,178,102,.14),transparent 55%),var(--ac-s1)}
.ac-hero h1,.ac-course-head h1{margin:0 0 8px;font-family:var(--font-syne);font-size:clamp(24px,4vw,34px);line-height:1.15;letter-spacing:.01em}
