.ac-section{margin-top:32px}
.ac-section h2{margin:0 0 12px;font-size:20px;line-height:1.3}
.ac-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,280px),1fr));gap:14px}
.ac-card{position:relative;display:flex;flex-direction:column;gap:8px;padding:18px;border:1px solid var(--ac-line);border-radius:12px;background:var(--ac-s2);color:var(--ac-t1)!important;text-decoration:none;min-width:0}
.ac-card::before{content:"";position:absolute;inset:0 0 auto 0;height:2px;border-radius:12px 12px 0 0;background:linear-gradient(135deg,#e6cf8f 0%,var(--ac-gold) 45%,var(--ac-gold-deep) 100%)}
.ac-card:hover{background:var(--ac-s3)}
