.ac-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:10px 16px;border-radius:10px;border:1px solid var(--ac-gold);background:var(--ac-gold);color:#131416;font-weight:700;font-size:15px;cursor:pointer;text-decoration:none}
