"use client"
import { useEffect, useMemo, useState } from "react"
import { AcademyShell } from "./AcademyShell"

type Lesson = { itemId: string; available: boolean; title?: string; state: string }
export type AcademyCourseSummary = {
  itemId: string; slug: string; versionId: string; version: number; title: string; description: string; category: string | null; objectives: string[]; estimatedMinutes: number | null
  publishedAt: string; updatedAt: string; modules: { title: string; lessons: Lesson[] }[]; progress: { completed: number; available: number; unavailable: number }; lastLessonItemId: string | null; lastViewedAt: string | null
}
export const CATEGORY_LABELS: Record<string, string> = {
  "getting-started": "Getting Started", services: "ScaleSmiths Services", "technical-knowledge": "Technical Knowledge", "digital-growth": "Digital Growth",
  "sales-fundamentals": "Sales Fundamentals", discovery: "Discovery", "commercial-policies": "Commercial Policies", "professional-conduct": "Professional Conduct", "advanced-opportunities": "Advanced Opportunities",
}
const STARTING_POINTS = ["getting-started", "professional-conduct"]
const date = (value: string) => new Date(value).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" })
const lessonCount = (c: AcademyCourseSummary) => c.modules.reduce((n, m) => n + m.lessons.length, 0)
const done = (c: AcademyCourseSummary) => c.progress.available > 0 && c.progress.completed === c.progress.available

function CourseCard({ c }: { c: AcademyCourseSummary }) {
  const pct = c.progress.available ? Math.round((c.progress.completed / c.progress.available) * 100) : 0
  const updated = c.modules.some((m) => m.lessons.some((l) => l.state === "updated"))
  return <a className="ac-card" href={`/partner/academy/${c.slug}`} data-course={c.slug}>
    <span className="ac-overline">{c.category ? CATEGORY_LABELS[c.category] ?? c.category : "Course"}</span>
    <h3>{c.title}</h3>
    <p>{c.description.split("\n")[0].replace(/[#*_`>]/g, "").slice(0, 180)}</p>
    <div className="ac-meta"><span>{c.modules.length} module{c.modules.length === 1 ? "" : "s"}</span><span>· {lessonCount(c)} lesson{lessonCount(c) === 1 ? "" : "s"}</span>{c.estimatedMinutes ? <span>· about {c.estimatedMinutes} min</span> : null}<span>· updated {date(c.updatedAt)}</span></div>
    <div className="ac-meta">
      {done(c) ? <span className="ac-chip ac-done">Completed</span> : c.progress.completed ? <span className="ac-chip">{c.progress.completed} of {c.progress.available} lessons read</span> : <span className="ac-chip">Not started</span>}
      {updated ? <span className="ac-chip ac-updated">Updated since you read it</span> : null}
      {c.progress.unavailable ? <span className="ac-chip">{c.progress.unavailable} lesson{c.progress.unavailable === 1 ? "" : "s"} under review</span> : null}
    </div>
    {c.progress.completed > 0 && <div className="ac-progress" role="progressbar" aria-label={`Your progress in ${c.title}`} aria-valuemin={0} aria-valuemax={c.progress.available} aria-valuenow={c.progress.completed}><span style={{ width: `${pct}%` }} /></div>}
  </a>
}

export function AcademyHome() {
  const [data, setData] = useState<{ courses: AcademyCourseSummary[] } | null>(null)
  const [error, setError] = useState("")
  const [query, setQuery] = useState("")
  const [category, setCategory] = useState("all")
  useEffect(() => {
    const controller = new AbortController()
    fetch("/api/partner/academy", { signal: controller.signal, cache: "no-store" })
      .then(async (r) => { const body = await r.json(); if (!r.ok) throw new Error(body.error || "The Academy could not be loaded."); setData(body) })
      .catch((e: Error) => { if (e.name !== "AbortError") setError(e.message) })
    return () => controller.abort()
  }, [])
  const courses = useMemo(() => data?.courses ?? [], [data])
  const categories = useMemo(() => [...new Set(courses.map((c) => c.category).filter(Boolean))] as string[], [courses])
  const term = query.trim().toLowerCase()
  const matching = courses.filter((c) => (category === "all" || c.category === category) && (!term || [c.title, c.description, ...c.objectives, ...c.modules.flatMap((m) => [m.title, ...m.lessons.map((l) => l.title ?? "")])].join(" ").toLowerCase().includes(term)))
  const continuing = courses.filter((c) => c.progress.completed > 0 && !done(c)).sort((a, b) => String(b.lastViewedAt).localeCompare(String(a.lastViewedAt)))
  const completed = courses.filter(done)
  const recent = [...courses].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)).slice(0, 3)
  const starting = courses.filter((c) => c.category && STARTING_POINTS.includes(c.category) && c.progress.completed === 0)
  return <AcademyShell current="home">
    <section className="ac-hero" aria-labelledby="academy-title">
      <p className="ac-overline">Partner Academy</p>
      <h1 id="academy-title">Learn at your own pace.</h1>
      <p>Short, approved lessons on ScaleSmiths services, honest selling and professional conduct. The Academy is optional and voluntary: nothing here is required, and nothing you read or answer affects your commission, prospects or standing. Your progress is private to you.</p>
    </section>
    {error && <p className="ac-error" role="alert">{error}</p>}
    {!data && !error && <p className="ac-muted" role="status">Loading the Academy…</p>}
    {data && !courses.length && <div className="ac-section ac-empty"><h2>No courses yet</h2><p>Courses appear here when ScaleSmiths has approved and published them. Nothing is available yet.</p></div>}
    {continuing.length > 0 && <section className="ac-section" aria-labelledby="continue"><h2 id="continue">Continue learning</h2><div className="ac-grid">{continuing.map((c) => <CourseCard key={c.itemId} c={c} />)}</div></section>}
    {starting.length > 0 && <section className="ac-section" aria-labelledby="start"><h2 id="start">Suggested starting points</h2><p className="ac-muted">A suggestion, not a requirement.</p><div className="ac-grid">{starting.map((c) => <CourseCard key={c.itemId} c={c} />)}</div></section>}
    {courses.length > 0 && <section className="ac-section" aria-labelledby="catalogue">
      <h2 id="catalogue">Course catalogue</h2>
      <div className="ac-filters">
        <label className="ac-field">Search courses<input type="search" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="For example: hosting, discovery, guarantees" /></label>
        <label className="ac-field">Category<select value={category} onChange={(e) => setCategory(e.target.value)}><option value="all">All categories</option>{categories.map((c) => <option key={c} value={c}>{CATEGORY_LABELS[c] ?? c}</option>)}</select></label>
      </div>
      <p className="ac-muted" aria-live="polite">{matching.length} of {courses.length} course{courses.length === 1 ? "" : "s"}</p>
      {matching.length ? <div className="ac-grid">{matching.map((c) => <CourseCard key={c.itemId} c={c} />)}</div> : <div className="ac-empty">No course matches that search.</div>}
    </section>}
    {recent.length > 0 && <section className="ac-section" aria-labelledby="recent"><h2 id="recent">Recently updated</h2><ul>{recent.map((c) => <li key={c.itemId}><a href={`/partner/academy/${c.slug}`}>{c.title}</a> <span className="ac-muted">· {date(c.updatedAt)}</span></li>)}</ul></section>}
    {completed.length > 0 && <section className="ac-section" aria-labelledby="completed"><h2 id="completed">Completed courses</h2><ul>{completed.map((c) => <li key={c.itemId}><a href={`/partner/academy/${c.slug}`}>{c.title}</a></li>)}</ul></section>}
    <section className="ac-section ac-help" aria-labelledby="help">
      <h2 id="help">Need help?</h2>
      <p>If a client asks something a lesson does not answer, do not improvise. Request a meeting from your <a href="/partner">Partner workspace</a>: technical scoping for technical questions, commercial assistance for pricing or terms, and escalation for complaints, mistakes or anything urgent.</p>
      <p className="ac-muted">Approved resources and the knowledge base will appear in the Resource Centre in a later release.</p>
    </section>
  </AcademyShell>
}

"use client"
import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { AcademyShell } from "./AcademyShell"
import { CATEGORY_LABELS, type AcademyCourseSummary } from "./AcademyHome"
import { SafeMarkdown } from "./SafeMarkdown"

type Option = { id: string; text: string }
type Check = { id: string; type: "single" | "multiple" | "true_false"; prompt: string; options: Option[]; lastAttempt?: { correct: boolean; given: string[]; answer: string[]; explanation: string } }
type LessonContent = { body: string; sources: string[]; checks: Check[] }
type CourseData = { course: AcademyCourseSummary & { modules: { title: string; summary?: string; lessons: { itemId: string; available: boolean; versionId?: string; version?: number; title?: string; readingMinutes?: number | null; state: string; completedAt?: string | null; publishedAt?: string }[] }[] }; lessons: Record<string, LessonContent> }
type Feedback = { correct: boolean; answer: string[]; explanation: string; given: string[] }

async function post(action: string, payload: Record<string, unknown>) {
  const r = await fetch("/api/partner/academy", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action, ...payload }) })
  const body = await r.json().catch(() => ({}))
  if (!r.ok) throw new Error(body.error || "That did not work. Please try again.")
  return body.result
}

function KnowledgeCheck({ q, courseVersionId, lessonVersionId }: { q: Check; courseVersionId: string; lessonVersionId: string }) {
  const [chosen, setChosen] = useState<string[]>([])
  const [feedback, setFeedback] = useState<Feedback | null>(q.lastAttempt ? { correct: q.lastAttempt.correct, answer: q.lastAttempt.answer, explanation: q.lastAttempt.explanation, given: q.lastAttempt.given } : null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState("")
  const multiple = q.type === "multiple"
  const text = (ids: string[]) => ids.map((id) => q.options.find((o) => o.id === id)?.text ?? id).join(", ")
  async function submit() {
    setBusy(true); setError("")
    try { setFeedback(await post("attempt_check", { courseVersionId, lessonVersionId, questionId: q.id, answer: chosen })) } catch (e) { setError((e as Error).message) } finally { setBusy(false) }
  }
  return <fieldset data-question={q.id}>
    <legend>{q.prompt}{multiple ? " (choose all that apply)" : ""}</legend>
    {q.options.map((o) => <label className="ac-option" key={o.id}>
      <input type={multiple ? "checkbox" : "radio"} name={`${lessonVersionId}-${q.id}`} value={o.id} checked={chosen.includes(o.id)} disabled={busy}
        onChange={(e) => setChosen(multiple ? (e.target.checked ? [...chosen, o.id] : chosen.filter((x) => x !== o.id)) : [o.id])} />
      <span>{o.text}</span></label>)}
    <button type="button" className="ac-button ac-secondary" onClick={submit} disabled={busy || !chosen.length}>{feedback ? "Try again" : "Check my answer"}</button>
    {error && <p className="ac-error" role="alert">{error}</p>}
    <div aria-live="polite">{feedback && <div className={`ac-feedback ${feedback.correct ? "ac-right" : "ac-wrong"}`}>
      <strong>{feedback.correct ? "Correct." : "Not quite."}</strong> {!feedback.correct && <>You chose: {text(feedback.given)}. The approved answer is: {text(feedback.answer)}. </>}
      <span>{feedback.explanation}</span></div>}</div>
  </fieldset>
}

export function AcademyCourse({ slug }: { slug: string }) {
  const [data, setData] = useState<CourseData | null>(null)
  const [error, setError] = useState("")
  const [current, setCurrent] = useState<string | null>(null)
  const [busy, setBusy] = useState(false)
  const [notice, setNotice] = useState("")
  const heading = useRef<HTMLHeadingElement>(null)
  const load = useCallback(async () => {
    const r = await fetch(`/api/partner/academy?course=${encodeURIComponent(slug)}`, { cache: "no-store" })
    const body = await r.json()
    if (!r.ok) throw new Error(body.error || "This course could not be loaded.")
    setData(body)
    return body as CourseData
  }, [slug])
  useEffect(() => {
    load().then((d) => {
      const wanted = new URLSearchParams(window.location.search).get("lesson")
      const flat = d.course.modules.flatMap((m) => m.lessons).filter((l) => l.available)
      setCurrent(flat.find((l) => l.itemId === wanted)?.itemId ?? flat.find((l) => l.itemId === d.course.lastLessonItemId)?.itemId ?? flat.find((l) => l.state !== "completed")?.itemId ?? flat[0]?.itemId ?? null)
    }).catch((e: Error) => setError(e.message))
  }, [load])
  const flat = useMemo(() => data?.course.modules.flatMap((m) => m.lessons) ?? [], [data])
  const lesson = flat.find((l) => l.itemId === current)
  const content = current ? data?.lessons[current] : undefined
  const available = flat.filter((l) => l.available)
  const index = available.findIndex((l) => l.itemId === current)
  useEffect(() => {
    if (!data || !lesson?.versionId) return
    const url = new URL(window.location.href); url.searchParams.set("lesson", lesson.itemId); window.history.replaceState(null, "", url)
    post("record_view", { courseVersionId: data.course.versionId, lessonVersionId: lesson.versionId }).catch(() => undefined)
  }, [data, lesson?.itemId, lesson?.versionId])
  const open = (id: string) => { setCurrent(id); setNotice(""); requestAnimationFrame(() => heading.current?.focus()) }
  async function complete() {
    if (!data || !lesson?.versionId) return
    setBusy(true); setNotice("")
    try { await post("complete_lesson", { courseVersionId: data.course.versionId, lessonVersionId: lesson.versionId }); await load(); setNotice("Marked as read. This is optional and private to you.") }
    catch (e) { setNotice((e as Error).message) } finally { setBusy(false) }
  }
  const stateLabel = (s: string) => s === "completed" ? "Read" : s === "updated" ? "Updated since you read it" : s === "unavailable" ? "Under review" : "Not read"
  return <AcademyShell current="course">
    <p><a href="/partner/academy">← Back to the course catalogue</a></p>
    {error && <p className="ac-error" role="alert">{error}</p>}
    {!data && !error && <p className="ac-muted" role="status">Loading the course…</p>}
    {data && <>
      <header className="ac-course-head">
        <p className="ac-overline">{data.course.category ? CATEGORY_LABELS[data.course.category] ?? data.course.category : "Course"} · version {data.course.version}</p>
        <h1>{data.course.title}</h1>
        <SafeMarkdown className="ac-prose" source={data.course.description} />
        {data.course.objectives.length > 0 && <><p className="ac-muted">After this course you should be able to:</p><ul>{data.course.objectives.map((o) => <li key={o}>{o}</li>)}</ul></>}
        <p className="ac-muted" aria-live="polite">{data.course.progress.completed} of {data.course.progress.available} available lessons read{data.course.progress.unavailable ? ` · ${data.course.progress.unavailable} under review` : ""}{data.course.estimatedMinutes ? ` · about ${data.course.estimatedMinutes} minutes in total` : ""}</p>
      </header>
      <div className="ac-course">
        <nav className="ac-outline" aria-label="Course contents">
          {data.course.modules.map((m, mi) => <div key={mi}><h2>{m.title}</h2><ol>{m.lessons.map((l) => <li key={l.itemId}>
            <button type="button" aria-current={l.itemId === current ? "true" : undefined} disabled={!l.available} onClick={() => open(l.itemId)}>
              <span>{l.available ? l.title : "Lesson under review"}</span><span className="ac-muted">{stateLabel(l.state)}</span></button></li>)}</ol></div>)}
        </nav>
        <article className="ac-lesson" aria-labelledby="lesson-title">
          {!lesson || !content ? <div className="ac-unavailable">Choose a lesson from the course contents.</div> : <>
            <div className="ac-lesson-head">
              <span className="ac-ribbon">Partner guidance · do not share as client material</span>
              <h2 id="lesson-title" ref={heading} tabIndex={-1}>{lesson.title}</h2>
              <p className="ac-muted">Lesson {index + 1} of {available.length}{lesson.readingMinutes ? ` · about ${lesson.readingMinutes} minutes` : ""} · approved version {lesson.version}{lesson.publishedAt ? `, published ${new Date(lesson.publishedAt).toLocaleDateString("en-GB")}` : ""}</p>
              {lesson.state === "updated" && <p className="ac-feedback ac-wrong">This lesson has been updated since you last read it. Your earlier reading is still recorded.</p>}
            </div>
            <SafeMarkdown className="ac-prose" source={content.body} />
            {content.sources.length > 0 && <p className="ac-muted">Sources: {content.sources.join(" · ")}</p>}
            {content.checks.length > 0 && <section className="ac-check" aria-labelledby="check-title"><h3 id="check-title">Optional knowledge check</h3><p className="ac-muted">Answers are checked straight away. Retry as often as you like; nothing here affects anything else.</p>
              {content.checks.map((q) => <KnowledgeCheck key={`${lesson.versionId}-${q.id}`} q={q} courseVersionId={data.course.versionId} lessonVersionId={lesson.versionId!} />)}</section>}
            <div className="ac-lesson-actions">
              <button type="button" className="ac-button ac-secondary" disabled={index <= 0} onClick={() => open(available[index - 1].itemId)}>← Previous lesson</button>
              {lesson.state === "completed" ? <span className="ac-chip ac-done">Read</span> : <button type="button" className="ac-button" onClick={complete} disabled={busy}>Mark as read (optional)</button>}
              <button type="button" className="ac-button ac-secondary" disabled={index < 0 || index >= available.length - 1} onClick={() => open(available[index + 1].itemId)}>Next lesson →</button>
            </div>
            <p aria-live="polite" className="ac-muted">{notice}</p>
            <p className="ac-muted">Not sure how this applies to a client? Request a <strong>technical scoping</strong> or <strong>commercial assistance</strong> meeting from your <a href="/partner">Partner workspace</a> rather than guessing.</p>
          </>}
        </article>
      </div>
    </>}
  </AcademyShell>
}

